42: function poly(points,fill,stroke=null){ctx.beginPath();points.forEach((p,i)=>{const q=project(p[0],p[1],p[2]||0);i?ctx.lineTo(q.x,q.y):ctx.moveTo(q.x,q.y)});ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke()}}
43: function ellipse(x,y,rx,ry,fill,alpha=1){const p=project(x,y);ctx.globalAlpha=alpha;ctx.beginPath();ctx.ellipse(p.x,p.y,rx*p.s,ry*p.s,0,0,Math.PI*2);ctx.fillStyle=fill;ctx.fill();ctx.globalAlpha=1}
44: function line(x1,y1,x2,y2,color,width=1){const a=project(x1,y1),b=project(x2,y2);ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.stroke()}
