54: function drawTree(t){const {x,y,h,r,variant}=t;ellipse(x,y,r*.9,r*.42,'#263f3f88');const s=project(x,y);let trunk=project(x,y,h*.65);ctx.strokeStyle='#765a43';ctx.lineWidth=Math.max(3,s.s*.17);ctx.beginPath();ctx.moveTo(s.x,s.y);ctx.lineTo(trunk.x,trunk.y);ctx.stroke();const tops=[[x,y,h],[x-r,y,h*.54],[x+r,y,h*.54],[x,y-r,h*.56],[x,y+r,h*.56]];poly(tops,variant===0?'#315a4b':variant===1?'#3e684c':variant===2?'#416c59':'#486e54');const p=project(x,y,h);ctx.beginPath();ctx.ellipse(p.x,p.y,r*s.s*.72,r*s.s*.36,0,0,Math.PI*2);ctx.fillStyle=variant%2?'#527d59':'#5f855f';ctx.fill();ctx.beginPath();ctx.ellipse(p.x-r*s.s*.2,p.y-r*s.s*.05,r*s.s*.28,r*s.s*.12,0,0,Math.PI*2);ctx.fillStyle='#78a56a';ctx.fill()}
