56: function drawBeacon(){const x=13.7,y=2.2;poly([[x-1,y,0],[x,y-.8,0],[x+1,y,0],[x,y+.8,0]],'#887e79');poly([[x-.55,y,.08],[x,y-.45,.08],[x+.55,y,.08],[x,y+.45,.08]],'#b6a387');poly([[x-.28,y,.1],[x,y-.22,.1],[x+.28,y,.1],[x,y+.22,.1]],'#e5c779');const p=project(x,y,1.2);const pulse=.5+Math.sin(performance.now()/450)*.12;ctx.save();ctx.shadowBlur=28*pulse;ctx.shadowColor='#ffe28e';ctx.fillStyle='#ffe9a8';ctx.beginPath();ctx.arc(p.x,p.y,8*pulse,0,7);ctx.fill();ctx.restore();for(let i=0;i<3;i++){const q=project(x+Math.cos(performance.now()/850+i*2)*.34,y+Math.sin(performance.now()/850+i*2)*.34,1.2+i*.14);ctx.fillStyle='#fff0c0';ctx.beginPath();ctx.arc(q.x,q.y,2,0,7);ctx.fill()}}
57: function drawShard(o){if(o.got)return;const b=Math.sin(performance.now()/240+o.x)*.1,p=project(o.x,o.y,.65+b);ctx.save();ctx.shadowBlur=18;ctx.shadowColor='#a9eaff';ctx.fillStyle='#b9eeff';ctx.beginPath();ctx.moveTo(p.x,p.y-10);ctx.lineTo(p.x+6,p.y);ctx.lineTo(p.x,p.y+9);ctx.lineTo(p.x-6,p.y);ctx.closePath();ctx.fill();ctx.fillStyle='#fff';ctx.fillRect(p.x-1,p.y-5,2,9);ctx.restore();ellipse(o.x,o.y,.32,.13,'#c5f5ff44')}
