67: function drawSlime(m){if(m.hp<=0)return;const p=project(m.x,m.y,.12+Math.sin(performance.now()/190+m.phase)*.055),r=p.s*.23;ellipse(m.x,m.y,.36,.15,'#294c5988');ctx.fillStyle='#8cdbb1';ctx.beginPath();ctx.ellipse(p.x,p.y-r*.5,r,r*.75,0,Math.PI,Math.PI*2);ctx.quadraticCurveTo(p.x+r,p.y+r*.3,p.x,p.y+r*.27);ctx.quadraticCurveTo(p.x-r,p.y+r*.3,p.x-r,p.y-r*.5);ctx.fill();ctx.fillStyle='#315d56';ctx.beginPath();ctx.arc(p.x-r*.3,p.y-r*.24,1.7,0,7);ctx.arc(p.x+r*.3,p.y-r*.24,1.7,0,7);ctx.fill();ctx.strokeStyle='#315d56';ctx.lineWidth=1;ctx.beginPath();ctx.arc(p.x,p.y-r*.05,3,0,.9);ctx.stroke()}
