72:  const items=[];trees.forEach(o=>items.push({d:o.x+o.y,type:'tree',o}));shardsPos.forEach(o=>items.push({d:o.x+o.y,type:'shard',o}));npcs.forEach(o=>items.push({d:o.x+o.y,type:'npc',o}));slimes.forEach(o=>items.push({d:o.x+o.y,type:'slime',o}));items.push({d:player.x+player.y,type:'player'});items.sort((a,b)=>a.d-b.d);
