77: function notify(msg){const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
78: function updateQuest(){document.querySelector('#count').textContent=`${shards} / 5`;document.querySelector('#progress').style.width=`${shards*20}%`;if(shards>=5){document.querySelector('#questTitle').textContent='Wake the valley beacon';document.querySelector('#questText').textContent='The five stars are singing. Return to the ancient beacon in the north.'}if(shards===5&&!ended)notify('All five stars found. The beacon awaits!')}
79: function near(a,b,dist=1.25){return Math.hypot(a.x-b.x,a.y-b.y)<dist}
80: function setDialogue(who,text,options){const d=document.querySelector('#dialogue');document.querySelector('#who').textContent=who;document.querySelector('#line').textContent=text;const box=document.querySelector('#choices');box.innerHTML='';options.forEach(o=>{const b=document.createElement('button');b.className='choice';b.textContent=o.label;b.onclick=o.action;box.append(b)});d.style.display='block';dialogueOpen=true}
