const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  const errors = [];
  page.on('pageerror', error => errors.push(error.message));
  await page.goto('http://localhost:3002');
  console.log('title:', await page.title());
  console.log('brand:', await page.locator('.brand h1').innerText());
  await page.screenshot({ path: '/tmp/opencode/star-fall.jpg', type: 'jpeg', quality: 80 });
  await page.locator('#start').click();
  console.log('intro hidden:', await page.locator('#intro').evaluate(el => el.classList.contains('hidden')));
  await page.keyboard.down('ArrowUp');
  await page.waitForTimeout(300);
  await page.keyboard.up('ArrowUp');
  console.log('canvas:', await page.locator('#game').evaluate(el => `${el.width}x${el.height}`));
  console.log('page errors:', errors.length ? errors.join('; ') : 'none');
  await browser.close();
})().catch(error => { console.error(error); process.exit(1); });
